import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`signage-quote`,heroTitle:`Turn signage specs into quotes in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded signage specs, plans fabrication and install work, and drafts a detailed quote automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your signage specs`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded signage specs, artwork notes, or site details. Build a complete signage quote. (1) Extract sign types, dimensions, materials, lighting, finishes, permit or install requirements, and site constraints from the uploaded files. (2) Organize the work into fabrication, printing, shipping, installation, and permit-related tasks where relevant. (3) Build pricing options with assumptions, alternates, and margin. (4) Highlight any client decisions, unknowns, or dependencies that should be confirmed before sending the quote. (5) Deliver a client-ready signage quote with line-item pricing, scope summary, and next steps.`,heroOverlaySteps:[`Extracting sign types, dimensions, materials, and site constraints from your files`,`Planning fabrication, printing, shipping, and installation requirements`,`Building pricing options with assumptions, alternates, and margin`,`Client-ready signage quote with scope summary, ready to send`],generatingSteps:[`Reading the uploaded specs, artwork notes, and site details`,`Designing an agent to organize fabrication, shipping, and installation requirements`,`Configuring quote logic for alternates, assumptions, and approval dependencies`,`Preparing a detailed signage quote with line items and next steps`],featureSectionTitle:`From spec sheet to client-ready quote`,featureCardTitles:[`Connects to your production workflow`,`Quotes built around fabrication and install reality`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, spec notes, and internal production workflows stay connected so quoting and revisions move faster.`,`Fabrication scope. Install assumptions. Alternates. Line-item pricing. Computer gives your team a signage quote draft that is ready for client review.`],capabilitySectionTitle:`Your quoting desk, on autopilot`,capabilitySectionSubtitle:`Upload the specs, get back a signage quote built around the real production scope.`,capabilityCards:[{title:`Spec Analysis`,description:`Computer can extract sign types, dimensions, materials, finishes, and install constraints from spec sheets, artwork notes, and site details.`},{title:`Fabrication Planning`,description:`Computer can organize printing, fabrication, lighting, shipping, and install requirements so the quote reflects the real production work.`},{title:`Pricing & Alternates`,description:`Computer can build line-item pricing, alternates, and assumptions so you can send a clearer quote without rebuilding the estimate manually.`},{title:`Connect Your Tools`,description:`Computer can keep quote drafts organized across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred materials, markup rules, and quote structure across sessions so every proposal stays consistent.`},{title:`Revision Follow-Up`,description:`Computer can update the quote as artwork, sign count, or install conditions change so your next draft is faster and easier to approve.`}]});export{t as default};
